From bbfbf84eafae73db0b184eee6a5bf9b4a32ab259 Mon Sep 17 00:00:00 2001
From: Christoph Wolk <cwo.kde@posteo.net>
Date: Tue, 10 Nov 2026 22:33:07 +0100
Subject: [PATCH] declarativeimports/core: allow pinning tooltip

ToolTipArea tooltips sensibly close when the pointer enters them, or in
case the tooltip is interactive, once the pointer leaves the tooltip -
having tooltips, in particularly large ones, stick around once they're
no longer in use is annoying.

However, interactive tooltips may sometimes wish to deviate from that.
For example, the Plasma task manager specifically allows the user to
open the tooltip when clicking grouped tasks, In that case, an easily
dismissed tooltip can be quite frustrating, as it prevents the user from
interacting with it.

So we add a new property pinOpen to ToolTipArea. When it is set, the
tooltip will not close if the user leaves the ToolTipArea nor the
tooltip itself, and other ToolTipAreas will not replace an open pinned
tooltip. It will only close if it is explicitly closed (e.g. with
hideToolTip()).

CCBUG: 518866
---
 src/declarativeimports/core/tooltiparea.cpp   | 22 ++++++++++++--
 src/declarativeimports/core/tooltiparea.h     | 18 ++++++++++++
 src/declarativeimports/core/tooltipdialog.cpp | 29 +++++++++++++++++--
 src/declarativeimports/core/tooltipdialog.h   |  5 ++++
 4 files changed, 70 insertions(+), 4 deletions(-)

diff --git a/src/declarativeimports/core/tooltiparea.cpp b/src/declarativeimports/core/tooltiparea.cpp
index 41e346e4c..1b555c445 100644
--- a/src/declarativeimports/core/tooltiparea.cpp
+++ b/src/declarativeimports/core/tooltiparea.cpp
@@ -33,6 +33,7 @@ ToolTipArea::ToolTipArea(QQuickItem *parent)
     , m_active(true)
     , m_interactive(false)
     , m_hideOnClick(true)
+    , m_pinOpen(false)
     , m_timeout(-1)
     , m_usingDialog(false)
 {
@@ -150,6 +151,7 @@ void ToolTipArea::showToolTip()
     dlg->setVisualParent(this);
     dlg->setMainItem(mainItem());
     dlg->setInteractive(m_interactive);
+    dlg->setPinOpen(m_pinOpen);

     switch (location) {
     case Plasma::Types::Floating:
@@ -285,6 +287,22 @@ void ToolTipArea::setHideOnClick(bool hideOnClick)
     Q_EMIT hideOnClickChanged();
 }

+void ToolTipArea::setPinOpen(bool pin)
+{
+    if (m_pinOpen == pin) {
+        return;
+    }
+
+    m_pinOpen = pin;
+
+    ToolTipDialog *dlg = tooltipDialogInstance();
+    if (dlg->owner() == this) {
+        dlg->setPinOpen(pin);
+    }
+
+    Q_EMIT pinOpenChanged();
+}
+
 void ToolTipArea::setTimeout(int timeout)
 {
     m_timeout = timeout;
@@ -351,7 +369,7 @@ void ToolTipArea::setContainsMouse(bool contains)
         m_containsMouse = contains;
         Q_EMIT containsMouseChanged();
     }
-    if (!contains && tooltipDialogInstance()->owner() == this) {
+    if (!contains && tooltipDialogInstance()->owner() == this && !tooltipDialogInstance()->pinOpen()) {
         tooltipDialogInstance()->dismiss();
     }
 }
@@ -377,7 +395,7 @@ void ToolTipArea::hoverEnterEvent(QHoverEvent *event)
         // It need to be considered only when other items can deal with tooltip area
         if (m_active) {
             tooltipDialogInstance()->keepalive();
-            if (s_dialog->owner() != this) {
+            if (s_dialog->owner() != this && !s_dialog->pinOpen()) {
                 // FIXME: showToolTip needs to be renamed in sync or something like that
                 showToolTip();
             }
diff --git a/src/declarativeimports/core/tooltiparea.h b/src/declarativeimports/core/tooltiparea.h
index 6951de824..d484dacf1 100644
--- a/src/declarativeimports/core/tooltiparea.h
+++ b/src/declarativeimports/core/tooltiparea.h
@@ -141,6 +141,20 @@ class ToolTipArea : public QQuickItem
      */
     Q_PROPERTY(bool hideOnClick MEMBER m_hideOnClick WRITE setHideOnClick NOTIFY hideOnClickChanged)

+    /*!
+     * \qmlproperty bool ToolTipArea::pinOpen
+     * If set to true, the tooltip will not close automatically once the pointer
+     * leaves it, and other tooltipareas will not replace it. This may be
+     * appropriate for complex interactive tooltips that the user explicitly
+     * activated by clicking, or that should support interactions like internal
+     * drag & drop. When this is set to false while this area's tooltip is open,
+     * it will be closed unless the area is still hovered, or the area is set to
+     * interactive and is currently hovered.
+     *
+     * The default is false.
+     */
+    Q_PROPERTY(bool pinOpen MEMBER m_pinOpen WRITE setPinOpen NOTIFY pinOpenChanged)
+
     /*!
      * \qmlproperty int ToolTipArea::timeout
      * Timeout in milliseconds after which the tooltip will hide itself.
@@ -182,6 +196,8 @@ public:

     void setHideOnClick(bool hideOnClick);

+    void setPinOpen(bool pin);
+
     void setTimeout(int timeout);

 public Q_SLOTS:
@@ -227,6 +243,7 @@ Q_SIGNALS:
     void activeChanged();
     void interactiveChanged();
     void hideOnClickChanged();
+    void pinOpenChanged();
     /*!
      * \qmlsignal ToolTipArea::aboutToShow
      *
@@ -264,6 +281,7 @@ private:
     bool m_active;
     bool m_interactive;
     bool m_hideOnClick;
+    bool m_pinOpen;
     int m_interval;
     int m_timeout;

diff --git a/src/declarativeimports/core/tooltipdialog.cpp b/src/declarativeimports/core/tooltipdialog.cpp
index 73b7675df..17ca1f706 100644
--- a/src/declarativeimports/core/tooltipdialog.cpp
+++ b/src/declarativeimports/core/tooltipdialog.cpp
@@ -16,12 +16,16 @@

 #include "plasmaquick.h"
 #include "plasmashellwaylandintegration.h"
+#include "popupplasmawindow.h"
+#include "tooltiparea.h"

 ToolTipDialog::ToolTipDialog()
     : PopupPlasmaWindow(QStringLiteral("widgets/tooltip"))
     , m_engine(PlasmaQuick::globalEngine())
     , m_hideTimeout(-1)
     , m_interactive(false)
+    , m_pinOpen(false)
+    , m_closeWhenUnpinned(true)
     , m_owner(nullptr)
 {
     Qt::WindowFlags flags = Qt::WindowDoesNotAcceptFocus | Qt::WindowStaysOnTopHint;
@@ -94,13 +98,18 @@ void ToolTipDialog::hideEvent(QHideEvent *event)
 bool ToolTipDialog::event(QEvent *e)
 {
     if (e->type() == QEvent::Enter) {
-        if (m_interactive) {
+        if (m_interactive || m_pinOpen) {
+            m_closeWhenUnpinned = !m_interactive;
             m_hideTimer.stop();
         } else {
             setVisible(false);
         }
     } else if (e->type() == QEvent::Leave) {
-        dismiss();
+        if (m_pinOpen) {
+            m_closeWhenUnpinned = true;
+        } else {
+            dismiss();
+        }
     }

     return PopupPlasmaWindow::event(e);
@@ -140,6 +149,22 @@ void ToolTipDialog::setInteractive(bool interactive)
     m_interactive = interactive;
 }

+bool ToolTipDialog::pinOpen()
+{
+    return m_pinOpen;
+}
+
+void ToolTipDialog::setPinOpen(bool pin)
+{
+    m_pinOpen = pin;
+    if (!pin && m_closeWhenUnpinned) {
+        auto area = dynamic_cast<ToolTipArea *>(m_owner);
+        if (area && !area->containsMouse()) {
+            dismiss();
+        }
+    }
+}
+
 void ToolTipDialog::valueChanged(const QVariant &value)
 {
     setPosition(value.toPoint());
diff --git a/src/declarativeimports/core/tooltipdialog.h b/src/declarativeimports/core/tooltipdialog.h
index 3af03f556..e713a3308 100644
--- a/src/declarativeimports/core/tooltipdialog.h
+++ b/src/declarativeimports/core/tooltipdialog.h
@@ -34,6 +34,9 @@ public:
     bool interactive();
     void setInteractive(bool interactive);

+    bool pinOpen();
+    void setPinOpen(bool pin);
+
     int hideTimeout() const;
     void setHideTimeout(int timeout);

@@ -60,6 +63,8 @@ private:
     QTimer m_hideTimer;
     int m_hideTimeout;
     bool m_interactive;
+    bool m_pinOpen;
+    bool m_closeWhenUnpinned;
     QObject *m_owner;
 };

