From 03fb77ace02d4d57a6e7f9e8b750d38e8c29d617 Mon Sep 17 00:00:00 2001
From: Christoph Wolk <cwo.kde@posteo.net>
Date: Tue, 10 Nov 2026 23:11:15 +0100
Subject: [PATCH 1/3] applets/taskmanager: pin the tooltip when clicked with
 option set

We allow the user to set the grouped task click action to "Show small
previews", which opens the tooltip. It still behaves mostly like a
tooltip and may well close while the user is interacting with it (e.g.
while dragging the scroll bar and landing outside the tooltip, or simply
by overshooting). This is not a good experience. For the specific case
that the user moves the cursor over another task, we have a bit of a
workaround, but even that may cause the scroll state to reset, and will
redraw the thumbnails (if enabled) which looks ugly.

Instead, set the tooltip to be pinned open when clicked. This makes the
tooltip stay open period, until either a task is clicked (in the tooltip
or task manager).

BUG: 518866
FIXED-IN: 6.9.0
---
 applets/taskmanager/qml/Task.qml | 5 +++--
 1 file changed, 3 insertions(+), 2 deletions(-)

diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..94c8f18e1c 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -82,6 +82,7 @@ PlasmaCore.ToolTipArea {
     active: !inPopup && !tasksRoot.groupDialog && task.contextMenu?.status !== PlasmaExtras.Menu.Open && task === (tasksRoot.toolTipOpenedByClick ?? task)
     interactive: model.IsWindow || mainItem.playerData
     hideOnClick: !(hasAudioStream && audioIndicatorsEnabled)
+    pinOpen: task === (tasksRoot.toolTipOpenedByClick)
     location: Plasmoid.location
     mainItem: !Plasmoid.configuration.showToolTips || !model.IsWindow ? pinnedAppToolTipDelegate : openWindowToolTipDelegate

@@ -196,8 +197,8 @@ PlasmaCore.ToolTipArea {
     }

     onContainsMouseChanged: {
-        if (tasksRoot.toolTipOpenedByClick && tasksRoot.toolTipOpenedByClick === mainItem.parentTask) {
-            tasksRoot.toolTipOpenedByClick.showToolTip();
+        if (tasksRoot.toolTipOpenedByClick) {
+            return;
         } else if (containsMouse) {
             task.forceActiveFocus(Qt.MouseFocusReason);
             task.updateMainItemBindings();
-- 
