From 1ac778333b40a13549ef5893aaf60875b4010728 Mon Sep 17 00:00:00 2001
From: Christoph Wolk <cwo.kde@posteo.net>
Date: Wed, 11 Nov 2026 19:01:01 +0100
Subject: [PATCH 2/3] applets/taskmanager: map drag&drop lookup to coordinate
 system

The MouseHandler looks up the current position's item in the ListView
when dragging things into it to figure out which window to raise. But
we're inside a scrollview, and the coordinates in the parent dropArea do
not necessarily map to the listview's position. This can cause the wrong
window to be raised. A similar issue can happen when the window is moved
from its optimal position to fit within the screen borders.

So first translate the current coordinates into ones mapping to the
ListView's contentItem, which corrects for the view being scrolled or
otherwise displaced from the origin.

CCBUG: 485511
---
 applets/taskmanager/qml/MouseHandler.qml | 4 +++-
 1 file changed, 3 insertions(+), 1 deletion(-)

diff --git a/applets/taskmanager/qml/MouseHandler.qml b/applets/taskmanager/qml/MouseHandler.qml
index 2fd85860c2..3e41d2af3d 100644
--- a/applets/taskmanager/qml/MouseHandler.qml
+++ b/applets/taskmanager/qml/MouseHandler.qml
@@ -43,7 +43,9 @@ DropArea {
         const rtlSpacerAdjustment = target.LayoutMirroring.enabled ? tasks.width - target.width : 0;
         let above;
         if (isGroupDialog) {
-            above = target.itemAt(event.x, event.y);
+            const targetListView = target as ListView
+            const positionInScrollView = mapToItem(targetListView.contentItem, event.x, event.y)
+            above = targetListView.itemAt(positionInScrollView.x, positionInScrollView.y)
         } else {
             above = target.childAt(event.x - rtlSpacerAdjustment, event.y);
         }
-- 
