From c70b86c5f2165763ade49b479ea0a33a21d9a9ca Mon Sep 17 00:00:00 2001
From: Christoph Wolk <cwo.kde@posteo.net>
Date: Wed, 11 Nov 2026 15:18:02 +0100
Subject: [PATCH 3/3] applets/taskmanager: open tooltip on drag

Currently, we always open the textual list when drag-hovering a grouped
task. This is not optimal - people who want window thumbnails don't get
them here, and unless you set it to show textual list on click, this is
the only place where users will see this. Instead, use the small window
preview/tooltip. It's active by default so should be familiar to users,
and has thumbnails unless the user turned them off. Drag-hovering over
a window in the tooltip should raise that window, as it does for the
current popup.

To do this, we reuse MouseHandler, which already has much of the
drag&drop logic and just needs a bit of extension. This will also allow
us to straightforwardly implement drag&drop reordering for the tooltip
in the future. We highlight the currently dragged-over delegate as
immediate feedback, and allow the user to auto-scroll in the ListView's
orientation when they are close to its edges.

For users who have configured taskmanager to show the textual list on
click, we keep the current textual list implementation on drag-hover as
well, as the user has indicated they want to work with this popup.

BUG: 485511
FIXED-IN: 6.9.0
---
 applets/taskmanager/qml/MouseHandler.qml    | 42 +++++++++++++++++++--
 applets/taskmanager/qml/ToolTipDelegate.qml | 26 +++++++++++++
 applets/taskmanager/qml/ToolTipInstance.qml |  5 ++-
 3 files changed, 68 insertions(+), 5 deletions(-)

diff --git a/applets/taskmanager/qml/MouseHandler.qml b/applets/taskmanager/qml/MouseHandler.qml
index 3e41d2af3d..1414c9f74b 100644
--- a/applets/taskmanager/qml/MouseHandler.qml
+++ b/applets/taskmanager/qml/MouseHandler.qml
@@ -8,6 +8,7 @@ import QtQuick

 import org.kde.taskmanager as TaskManager
 import org.kde.plasma.plasmoid
+import org.kde.kirigami as Kirigami
 import plasma.applet.org.kde.plasma.taskmanager as TaskManagerApplet

 DropArea {
@@ -18,6 +19,7 @@ DropArea {
     property Item ignoredItem
     property Item hoveredItem
     property bool isGroupDialog: false
+    property bool isToolTip: false
     property bool moved: false

     property alias handleWheelEvents: wheelHandler.handleWheelEvents
@@ -27,6 +29,9 @@ DropArea {
         if (event.formats.indexOf("text/x-plasmoidservicename") >= 0) {
             event.accepted = false;
         }
+        if (isToolTip) {
+            target.autoScroll = true
+        }
         if (target.animating) { // Not all targets have an animating property
             target.animating = false;
         }
@@ -42,7 +47,7 @@ DropArea {
         // them, or we end thinking we're dragging way right of where we actually are.
         const rtlSpacerAdjustment = target.LayoutMirroring.enabled ? tasks.width - target.width : 0;
         let above;
-        if (isGroupDialog) {
+        if (isGroupDialog || isToolTip) {
             const targetListView = target as ListView
             const positionInScrollView = mapToItem(targetListView.contentItem, event.x, event.y)
             above = targetListView.itemAt(positionInScrollView.x, positionInScrollView.y)
@@ -76,6 +81,14 @@ DropArea {
             ignoredItem = null;
         }

+        if (isToolTip) {
+            // Trigger autoscroll.
+            target.scrollLeft = (event.x < (Kirigami.Units.gridUnit * 3));
+            target.scrollRight = (event.x > width - (Kirigami.Units.gridUnit * 3));
+            target.scrollUp = (event.y < (Kirigami.Units.gridUnit * 3));
+            target.scrollDown = (event.y > height - (Kirigami.Units.gridUnit * 3));
+        }
+
         if (tasksModel.sortMode === TaskManager.TasksModel.SortManual && tasks.dragSource) {
             // Reject drags between different TaskList instances.
             if (tasks.dragSource.parent !== above.parent) {
@@ -104,6 +117,13 @@ DropArea {
     onExited: {
         hoveredItem = null;
         activationTimer.stop();
+        if (isToolTip) {
+            target.autoScroll = false
+            target.scrollUp = false
+            target.scrollDown = false
+            target.scrollLeft = false
+            target.scrollRight = false
+        }
     }

     onDropped: event => {
@@ -136,6 +156,13 @@ DropArea {
         }
     }

+    Binding {
+        when: dropArea.isToolTip && !!dropArea.hoveredItem
+        target: dropArea.hoveredItem
+        property: "forceHighlight"
+        value: true
+    }
+
     Timer {
         id: ignoreItemTimer

@@ -155,9 +182,18 @@ DropArea {

         onTriggered: {
             if (parent.hoveredItem.model.IsGroupParent) {
-                TaskManagerApplet.TaskTools.createGroupDialog(parent.hoveredItem, tasks);
+                if (Plasmoid.configuration.groupedTaskVisualization == 3) {
+                    TaskManagerApplet.TaskTools.createGroupDialog(parent.hoveredItem, tasks);
+                } else {
+                    parent.hoveredItem.showToolTip()
+                    parent.hoveredItem.updateMainItemBindings()
+                }
             } else if (!parent.hoveredItem.model.IsLauncher) {
-                tasksModel.requestActivate(parent.hoveredItem.modelIndex());
+                if (dropArea.isToolTip) {
+                    tasksModel.requestActivate(parent.hoveredItem.submodelIndex);
+                } else {
+                    tasksModel.requestActivate(parent.hoveredItem.modelIndex());
+                }
             }
         }
     }
diff --git a/applets/taskmanager/qml/ToolTipDelegate.qml b/applets/taskmanager/qml/ToolTipDelegate.qml
index 014e954c5c..3b130a738b 100644
--- a/applets/taskmanager/qml/ToolTipDelegate.qml
+++ b/applets/taskmanager/qml/ToolTipDelegate.qml
@@ -124,6 +124,20 @@ Loader {

                 model: delegateModel

+                property bool scrollLeft: false
+                property bool scrollRight: false
+                property bool scrollUp: false
+                property bool scrollDown: false
+                property bool autoScroll: false
+
+                onScrollLeftChanged: contentX = scrollLeft && orientation == ListView.Horizontal ? originX : contentX
+                onScrollRightChanged: contentX = scrollRight  && orientation == ListView.Horizontal ? originX + contentWidth - width : contentX
+                onScrollUpChanged: contentY = scrollUp  && orientation == ListView.Vertical ? originY : contentY
+                onScrollDownChanged: contentY = scrollDown  && orientation == ListView.Vertical ? originY + contentHeight - height : contentY
+
+                Behavior on contentX { id: smoothX; enabled: groupToolTipListView.autoScroll; SmoothedAnimation { velocity: 700 } }
+                Behavior on contentY { id: smoothY; enabled: groupToolTipListView.autoScroll; SmoothedAnimation { velocity: 700 } }
+
                 orientation: toolTipDelegate.isVerticalPanel || !Plasmoid.configuration.showToolTips ? ListView.Vertical : ListView.Horizontal
                 reuseItems: true

@@ -195,6 +209,18 @@ Loader {
                         }
                     }
                 }
+
+            }
+        }
+    }
+    MouseHandler {
+        target: (toolTipDelegate.item as PlasmaComponents3.ScrollView)?.contentItem ?? null
+        anchors.fill: parent
+        isToolTip: true
+
+        onContainsDragChanged: {
+            if (!containsDrag && !toolTipDelegate.parentTask.pinOpen) {
+                toolTipDelegate.parentTask.hideToolTip()
             }
         }
     }
diff --git a/applets/taskmanager/qml/ToolTipInstance.qml b/applets/taskmanager/qml/ToolTipInstance.qml
index 5a42d24a17..1b96896e1a 100644
--- a/applets/taskmanager/qml/ToolTipInstance.qml
+++ b/applets/taskmanager/qml/ToolTipInstance.qml
@@ -36,6 +36,7 @@ ColumnLayout {
     required property bool isReadyForPainting
     required property bool isExcludedFromCapture

+    property bool forceHighlight: false
     property bool hasTrackInATitle: false
     property int orientation: ListView.Vertical // vertical for compact single-window tooltips

@@ -276,7 +277,7 @@ ColumnLayout {
             anchors.fill: headerItem
             anchors.margins: -headerItem.Layout.margins
             z: -1
-            visible: headerHoverHandler.hovered
+            visible: headerHoverHandler.hovered || (!Plasmoid.configuration.showToolTips && root.forceHighlight)
             pressed: headerTapHandler.pressed
             hovered: true
         }
@@ -298,7 +299,7 @@ ColumnLayout {
         // There's no PlasmaComponents3 version
         PlasmaExtras.Highlight {
             anchors.fill: parent
-            visible: hoverHandler.hovered
+            visible: hoverHandler.hovered || (Plasmoid.configuration.showToolTips && root.forceHighlight)
             pressed: tapHandler.pressed
             hovered: true
